def compare(
    before: ParsedJournal,
    after: ParsedJournal,
    console: str | None = None,
    targets: Targets = Targets(),
) -> list[dict]:
    b = console_metrics(before, console, targets=targets) | _extra(
        before, console
    )
    a = console_metrics(after, console, targets=targets) | _extra(
        after, console
    )
    b["high_pct"], a["high_pct"] = (
        b["priority_mix"]["High"],
        a["priority_mix"]["High"],
    )
    out = []
    for key, label, target, _ in ROWS:
        bv, av = float(b[key]), float(a[key])
        change = (100.0 * (av - bv) / bv) if bv else 0.0
        out.append(
            {
                "metric": label,
                "before": bv,
                "after": av,
                "change_pct": change,
                "target": target or "",
            }
        )
    return out

episode.code:
@dataclass(slots=True)
class Episode:
    eventid: str
    source: str
    displaypath: str
    priority: int
    console: str
    active: datetime | None = None
    ack: datetime | None = None
    clear: datetime | None = None
    shelved: bool = False

    @property
    def annunciated(self) -> bool:
        """Shown to the operator: it went active and was not shelved."""
        return self.active is not None and not self.shelved

    def duration(self, end: datetime) -> float:
        """Seconds active; an alarm still active counts to `end`."""
        stop = self.clear or end
        return (stop - self.active).total_seconds() if self.active else 0.0

    def time_to_ack(self) -> float | None:
        if self.active and self.ack:
            return (self.ack - self.active).total_seconds()
        return None

